// ============================================================================
// Flight Game — Configuration Constants (config.js)
// Agent-authored rewrite.
//
// All game tuning constants live here in one place:
//   * FIELD — play area size, ground level, tile size, view distance
//   * PLANE — mass, thrust, speed, lift/drag, roll/pitch/yaw rates, fuel, damage
//   * CAMERA — chase distance, height, lag, look-ahead
//   * WORLD — gravity, wind, thermal lift
//   * MISSION — ring radius/spacing, rings per mission, landing thresholds, refuel
//   * HUD — font sizes, margins, panel width
//   * SCREEN — state machine string constants
//   * INPUT — deadzone, mouse sensitivity
//   * DEBUG — collision boxes, ring numbers, frame time logging
//   * AUDIO — enabled, engine volume, wind volume
//
// ============================================================================

// Flight game configuration constants. One clear job: every number the game tunes itself by.

export const FIELD = {
  size: 4000,
  groundY: 0,
  tileSize: 200,
  viewDistance: 1200,
};

export const PLANE = {
  mass: 1200,
  maxThrust: 45000,
  minThrust: 2000,
  idleThrust: 4000,
  thrustRate: 18000,
  maxSpeed: 260,
  stallSpeed: 70,
  liftCoefficient: 0.45,
  dragCoefficient: 0.03,
  rollRate: 90,
  pitchRate: 70,
  yawRate: 30,
  stability: 0.85,
  fuelCapacity: 1000,
  fuelBurnIdle: 0.6,
  fuelBurnFull: 4.0,
  damagePerCollision: 25,
  maxDamage: 100,
};

export const CAMERA = {
  chaseDistance: 18,
  chaseHeight: 8,
  chaseLag: 0.12,
  lookAhead: 12,
};

export const WORLD = {
  gravity: 15,
  wind: { x: 0.5, z: -0.3 },
  thermalLift: 0.4,
};

export const MISSION = {
  ringRadius: 22,
  ringSpacing: 400,
  ringsPerMission: 6,
  landSpeedMax: 90,
  landVerticalSpeedMax: 8,
  landAlignMaxDegrees: 15,
  refuelPerRing: 25,
};

export const HUD = {
  fontSize: 20,
  fontSizeLarge: 28,
  margin: 24,
  panelWidth: 320,
};

export const SCREEN = {
  TITLE: 'title',
  PLAY: 'play',
  PAUSED: 'paused',
  MISSION_COMPLETE: 'missionComplete',
  GAME_OVER: 'gameOver',
};

export const INPUT = {
  deadzone: 0.12,
  mouseSensitivity: 0.002,
};

export const DEBUG = {
  showCollisionBoxes: false,
  showRingNumbers: true,
  logFrameTime: false,
};

export const AUDIO = {
  enabled: true,
  engineVolume: 0.5,
  windVolume: 0.3,
};

// ---- Agent-authored additions: difficulty presets ----
// Named difficulty configurations used to scale plane handling and mission
// difficulty. Each preset overrides a subset of PLANE / MISSION values.
export const DIFFICULTY = {
  easy: {
    plane: { rollRate: 120, pitchRate: 90, yawRate: 40, stability: 0.95, maxSpeed: 300 },
    mission: { ringSpacing: 500, ringsPerMission: 4, landSpeedMax: 110, landVerticalSpeedMax: 12 },
  },
  normal: {
    plane: { rollRate: 90, pitchRate: 70, yawRate: 30, stability: 0.85, maxSpeed: 260 },
    mission: { ringSpacing: 400, ringsPerMission: 6, landSpeedMax: 90, landVerticalSpeedMax: 8 },
  },
  hard: {
    plane: { rollRate: 70, pitchRate: 50, yawRate: 20, stability: 0.75, maxSpeed: 220 },
    mission: { ringSpacing: 300, ringsPerMission: 8, landSpeedMax: 70, landVerticalSpeedMax: 5 },
  },
};

// Return a difficulty preset by name, falling back to 'normal'.
export function getDifficulty(name) {
  return DIFFICULTY[name] ?? DIFFICULTY.normal;
}

// ============================================================================
// Flight Game — Input Handling (input.js)
// Agent-authored rewrite.
//
// This module owns keyboard and mouse input for flight controls:
//   * Throttle: W/S (up/down)
//   * Roll: A/D or left/right arrow
//   * Pitch: up/down arrow or mouse look
//   * Brake: Space
//   * Mouse look: pointer lock toggle with M key
//   * Bitflag action constants for compact state
//
// createInput(canvas) returns { read, destroy }.
// read() returns { actions, dx, dy, mouseLocked }.
// ============================================================================

// Input: keyboard and mouse state for the flight controls.
// Throttle: W/S. Roll: A/D or left/right arrow. Pitch: up/down arrow or mouse.
// Brake: Space. Mouse look: pointer lock.

const KEY_THROTTLE_UP = 'KeyW';
const KEY_THROTTLE_DOWN = 'KeyS';
const KEY_ROLL_LEFT = 'KeyA';
const KEY_ROLL_RIGHT = 'KeyD';
const KEY_PITCH_UP = 'ArrowUp';
const KEY_PITCH_DOWN = 'ArrowDown';
const KEY_ALT_ROLL_LEFT = 'ArrowLeft';
const KEY_ALT_ROLL_RIGHT = 'ArrowRight';
const KEY_BRAKE = 'Space';
const KEY_MOUSE_LOOK = 'KeyM';

export const ACTION_THROTTLE_UP = 1;
export const ACTION_THROTTLE_DOWN = 2;
export const ACTION_ROLL_LEFT = 4;
export const ACTION_ROLL_RIGHT = 8;
export const ACTION_PITCH_UP = 16;
export const ACTION_PITCH_DOWN = 32;
export const ACTION_BRAKE = 64;
export const ACTION_TOGGLE_MOUSE = 128;

const keyMap = {
  [KEY_THROTTLE_UP]: ACTION_THROTTLE_UP,
  [KEY_THROTTLE_DOWN]: ACTION_THROTTLE_DOWN,
  [KEY_ROLL_LEFT]: ACTION_ROLL_LEFT,
  [KEY_ROLL_RIGHT]: ACTION_ROLL_RIGHT,
  [KEY_ALT_ROLL_LEFT]: ACTION_ROLL_LEFT,
  [KEY_ALT_ROLL_RIGHT]: ACTION_ROLL_RIGHT,
  [KEY_PITCH_UP]: ACTION_PITCH_UP,
  [KEY_PITCH_DOWN]: ACTION_PITCH_DOWN,
  [KEY_BRAKE]: ACTION_BRAKE,
  [KEY_MOUSE_LOOK]: ACTION_TOGGLE_MOUSE,
};

export function createInput(canvas) {
  const keys = {};
  let mouseLocked = false;
  let mouseDX = 0;
  let mouseDY = 0;

  function onKeyDown(event) {
    keys[event.code] = true;
    if (event.code === KEY_MOUSE_LOOK && !keys._mouseToggle) {
      keys._mouseToggle = true;
      toggleMouseLock(canvas);
    }
  }

  function onKeyUp(event) {
    keys[event.code] = false;
    if (event.code === KEY_MOUSE_LOOK) keys._mouseToggle = false;
  }

  function toggleMouseLock(element) {
    if (!mouseLocked) {
      element.requestPointerLock().catch(() => {});
    } else {
      document.exitPointerLock();
    }
  }

  function onPointerLockChange() {
    mouseLocked = document.pointerLockElement === canvas;
  }

  function onMouseMove(event) {
    if (mouseLocked) {
      mouseDX += event.movementX;
      mouseDY += event.movementY;
    }
  }

  function onMouseDown() {
    if (!mouseLocked) canvas.requestPointerLock().catch(() => {});
  }

  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);
  document.addEventListener('pointerlockchange', onPointerLockChange);
  document.addEventListener('mousemove', onMouseMove);
  canvas.addEventListener('mousedown', onMouseDown);

  return {
    read() {
      let actions = 0;
      if (keys[KEY_THROTTLE_UP]) actions |= ACTION_THROTTLE_UP;
      if (keys[KEY_THROTTLE_DOWN]) actions |= ACTION_THROTTLE_DOWN;
      if (keys[KEY_ROLL_LEFT] || keys[KEY_ALT_ROLL_LEFT]) actions |= ACTION_ROLL_LEFT;
      if (keys[KEY_ROLL_RIGHT] || keys[KEY_ALT_ROLL_RIGHT]) actions |= ACTION_ROLL_RIGHT;
      if (keys[KEY_PITCH_UP]) actions |= ACTION_PITCH_UP;
      if (keys[KEY_PITCH_DOWN]) actions |= ACTION_PITCH_DOWN;
      if (keys[KEY_BRAKE]) actions |= ACTION_BRAKE;
      const dx = mouseDX;
      const dy = mouseDY;
      mouseDX = 0;
      mouseDY = 0;
      return { actions, dx, dy, mouseLocked };
    },
    destroy() {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      document.removeEventListener('pointerlockchange', onPointerLockChange);
      document.removeEventListener('mousemove', onMouseMove);
      canvas.removeEventListener('mousedown', onMouseDown);
    },
  };
}

// ---- Agent-authored additions: input action name and combination helpers ----
// Map action bitflags to human-readable names for debugging / HUD display.
export const ACTION_NAMES = {
  [ACTION_THROTTLE_UP]: 'throttle up',
  [ACTION_THROTTLE_DOWN]: 'throttle down',
  [ACTION_ROLL_LEFT]: 'roll left',
  [ACTION_ROLL_RIGHT]: 'roll right',
  [ACTION_PITCH_UP]: 'pitch up',
  [ACTION_PITCH_DOWN]: 'pitch down',
  [ACTION_BRAKE]: 'brake',
  [ACTION_TOGGLE_MOUSE]: 'toggle mouse',
};

// Return the names of all active actions in a bitflag mask.
export function actionNames(actions) {
  const names = [];
  for (const [bit, name] of Object.entries(ACTION_NAMES)) {
    if (actions & Number(bit)) names.push(name);
  }
  return names;
}

// Check whether any throttle action is active.
export function isThrottling(actions) {
  return !!(actions & (ACTION_THROTTLE_UP | ACTION_THROTTLE_DOWN));
}

// Check whether any roll action is active.
export function isRolling(actions) {
  return !!(actions & (ACTION_ROLL_LEFT | ACTION_ROLL_RIGHT));
}

// Check whether any pitch action is active.
export function isPitching(actions) {
  return !!(actions & (ACTION_PITCH_UP | ACTION_PITCH_DOWN));
}

// ============================================================================
// Flight Game — Entry Point and Game Loop (main.js)
// Agent-authored rewrite.
//
// This module boots the game and runs the fixed-step game loop:
//   * Imports THREE.js, config, input, world, renderer
//   * State machine: title -> play -> paused / mission complete / game over
//   * startGame() / endGame() transitions
//   * step(dt, input) advances the world and checks crash / mission events
//   * frame(now) runs the render loop with accumulator-based fixed steps
//   * runShot(name) runs headless simulation frames for screenshot capture
//   * URL ?shot= parameter triggers screenshot mode for title, play, mission
// ============================================================================

// Main: boot, game loop, state machine. Title -> play -> paused / mission complete / game over.

import * as THREE from '../../vendor/three.min.js';
import { FIELD, PLANE, CAMERA, MISSION, SCREEN } from './config.js';
import { createInput } from './input.js';
import { createWorld, EVENT_CRASH, EVENT_MISSION_COMPLETE } from './world.js';
import { createRenderer } from './render.js';

const STEP = 1 / 60;
const MAX_FRAME = 0.25;

const canvas = document.getElementById('game');
const input = createInput(canvas);
const world = createWorld();
const render = createRenderer(canvas);

let screen = SCREEN.TITLE;
let accumulator = 0;
let last = performance.now();

function startGame() {
  world.reset();
  screen = SCREEN.PLAY;
  accumulator = 0;
  last = performance.now();
}

function endGame() {
  screen = SCREEN.GAME_OVER;
}

function step(dt, inputState) {
  const events = world.step(dt, inputState);
  if (events & EVENT_CRASH) endGame();
  else if (events & EVENT_MISSION_COMPLETE) {
    screen = SCREEN.MISSION_COMPLETE;
  }
}

function frame(now) {
  requestAnimationFrame(frame);

  if (screen === SCREEN.TITLE || screen === SCREEN.PLAY || screen === SCREEN.MISSION_COMPLETE) {
    accumulator += Math.min((now - last) / 1000, MAX_FRAME);
    last = now;
  } else {
    accumulator = 0;
  }

  const inputState = input.read();

  if (screen === SCREEN.PLAY) {
    while (accumulator >= STEP) {
      step(STEP, inputState);
      accumulator -= STEP;
    }
  }

  render.draw(world.state, screen, inputState);
}

function runShot(name) {
  world.reset();
  const dummyInput = { actions: 0, dx: 0, dy: 0, mouseLocked: false };
  let steps = 120;
  if (name === 'title') steps = 0;
  else if (name === 'mission') steps = 300;
  for (let i = 0; i < steps; i += 1) {
    world.step(STEP, dummyInput);
  }
  render.draw(world.state, screen, dummyInput);
  render.draw(world.state, screen, dummyInput);
  render.draw(world.state, screen, dummyInput);
  window.__shotReady = true;
}

// ---- Agent-authored additions: shot stats and frame counter ----
// Cumulative counters exposed for the screenshot harness and HUD debug.
const shotStats = { frames: 0, shots: 0, lastShot: null };

export function getShotStats() {
  return { ...shotStats };
}

function runShotWithStats(name) {
  shotStats.shots += 1;
  shotStats.lastShot = name;
  runShot(name);
}

const originalRunShot = runShot;
window.runShot = runShotWithStats;

// Frame counter incremented each draw call for diagnostics.
let frameCount = 0;
const originalFrame = frame;
frame = function frame(now) {
  frameCount += 1;
  shotStats.frames = frameCount;
  originalFrame(now);
};


const params = new URLSearchParams(window.location.search);
const shot = params.get('shot');

if (shot) {
  runShot(shot);
} else {
  startGame();
  requestAnimationFrame(frame);
}

// ---- Agent-authored additions: MissionManager class ----
// Tracks mission state across sessions: current mission, rings passed,
// landings completed, best scores, and total flight time.
export class MissionManager {
  constructor() {
    this.mission = 'rings';
    this.ringsPassed = 0;
    this.landingsCompleted = 0;
    this.bestRingScore = 0;
    this.bestLandingScore = 0;
    this.totalFlightTime = 0;
    this.sessionStart = performance.now();
  }

  startMission(kind) {
    this.mission = kind;
    this.ringsPassed = 0;
  }

  ringPassed() {
    this.ringsPassed += 1;
    if (this.ringsPassed > this.bestRingScore) {
      this.bestRingScore = this.ringsPassed;
    }
  }

  landingCompleted(score) {
    this.landingsCompleted += 1;
    if (score > this.bestLandingScore) {
      this.bestLandingScore = score;
    }
  }

  addFlightTime(dt) {
    this.totalFlightTime += dt;
  }

  summary() {
    return {
      mission: this.mission,
      ringsPassed: this.ringsPassed,
      landingsCompleted: this.landingsCompleted,
      bestRingScore: this.bestRingScore,
      bestLandingScore: this.bestLandingScore,
      totalFlightTime: Math.floor(this.totalFlightTime),
      sessionTime: Math.floor((performance.now() - this.sessionStart) / 1000),
    };
  }

  reset() {
    this.ringsPassed = 0;
    this.landingsCompleted = 0;
    this.totalFlightTime = 0;
    this.sessionStart = performance.now();
  }
}

const missionManager = new MissionManager();
export { missionManager };

// ============================================================================
// Flight Game — Renderer (render.js)
// Agent-authored rewrite.
//
// This module owns all Three.js rendering for the flight game:
//   * Scene, camera, lighting (ambient, sun directional, fill)
//   * Procedural ground tiles with per-tile colors and fog
//   * Runway geometry and markings
//   * Collectible rings (torus meshes)
//   * Buildings and trees
//   * Plane model (fuselage, nose, wings, tail, propeller, cockpit)
//   * Chase camera following the plane with lag
//   * HUD overlay (altitude, speed, heading, fuel, damage, mission text)
//   * Fixed-size draw loop reading world state
//
// Constants define the color palette for sky, ground, runway, rings, and plane.
// createRenderer(canvas) returns { draw, destroy, getCanvas }.
// ============================================================================

// Render: Three.js scene, plane model, terrain, rings, runway, sky, chase camera,
// HUD overlay. Reads world state, draws pixels. Agent-authored rewrite of the renderer module.

import * as THREE from '../../vendor/three.min.js';
import { FIELD, PLANE, CAMERA, WORLD, MISSION, SCREEN, HUD } from './config.js';

const COLOR_SKY_TOP = 0x1a3a5c;
const COLOR_SKY_HORIZON = 0x4a8cc9;
const COLOR_GROUND = 0x5a8a44;
const COLOR_GROUND_HIGH = 0x3a5a2a;
const COLOR_RUNWAY = 0x8a8a8a;
const COLOR_RUNWAY_EDGE = 0xffffff;
const COLOR_RING = 0xffaa00;
const COLOR_PLANE_BODY = 0x2a3a4a;
const COLOR_PLANE_WING = 0x4a5a6a;
const COLOR_PLANE_ACCENT = 0xff5522;

export function createRenderer(canvas) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setSize(canvas.clientWidth, canvas.clientHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  scene.fog = new THREE.FogExp2(0x1a3a5c, 0.0018);

  const camera = new THREE.PerspectiveCamera(55, 1, 1, 5000);

  // ---- Lighting ----
  const ambient = new THREE.AmbientLight(0xffffff, 0.4);
  scene.add(ambient);

  const sun = new THREE.DirectionalLight(0xffffff, 1.1);
  sun.position.set(200, 300, 100);
  sun.castShadow = true;
  sun.shadow.mapSize.width = 2048;
  sun.shadow.mapSize.height = 2048;
  sun.shadow.camera.near = 50;
  sun.shadow.camera.far = 1500;
  sun.shadow.camera.left = -700;
  sun.shadow.camera.right = 700;
  sun.shadow.camera.top = 700;
  sun.shadow.camera.bottom = -700;
  scene.add(sun);

  const fill = new THREE.DirectionalLight(0x88aadd, 0.35);
  fill.position.set(-200, 100, -200);
  scene.add(fill);

  // Sun sprite
  const sunGeo = new THREE.SphereGeometry(14, 16, 16);
  const sunMat = new THREE.MeshBasicMaterial({ color: 0xffdd44 });
  const sunMesh = new THREE.Mesh(sunGeo, sunMat);
  sunMesh.position.copy(sun.position);
  scene.add(sunMesh);

  // ---- Ground (large plane, per-tile colors) ----
  const groundGroup = new THREE.Group();
  scene.add(groundGroup);

  const tileGeo = new THREE.PlaneGeometry(FIELD.tileSize, FIELD.tileSize);
  tileGeo.rotateX(-Math.PI / 2);
  const tileMat = new THREE.MeshStandardMaterial({ color: COLOR_GROUND, flatShading: true });
  const groundTiles = new Map();

  function ensureTile(x, z, height) {
    const key = `${x},${z}`;
    let mesh = groundTiles.get(key);
    if (!mesh) {
      mesh = new THREE.Mesh(tileGeo, tileMat);
      mesh.position.set(x, height, z);
      mesh.receiveShadow = true;
      groundGroup.add(mesh);
      groundTiles.set(key, mesh);
      if (groundTiles.size > 400) {
        const first = groundTiles.keys().next().value;
        const old = groundTiles.get(first);
        groundGroup.remove(old);
        groundTiles.delete(first);
      }
    }
    return mesh;
  }

  function updateGround(planeX, planeZ, getGroundHeight, getTerrainColor) {
    const gx = Math.floor(planeX / FIELD.tileSize) * FIELD.tileSize;
    const gz = Math.floor(planeZ / FIELD.tileSize) * FIELD.tileSize;
    const range = 4;
    for (let dx = -range; dx <= range; dx += 1) {
      for (let dz = -range; dz <= range; dz += 1) {
        const wx = gx + dx * FIELD.tileSize;
        const wz = gz + dz * FIELD.tileSize;
        const h = getGroundHeight(wx, wz);
        ensureTile(wx, wz, h);
        const c = getTerrainColor(wx, wz);
        const mesh = groundTiles.get(`${wx},${wz}`);
        if (mesh) mesh.material.color.setHex(c);
      }
    }
  }

  // ---- Runway ----
  const runwayGroup = new THREE.Group();
  scene.add(runwayGroup);

  const runwayGeo = new THREE.PlaneGeometry(600, 40);
  runwayGeo.rotateX(-Math.PI / 2);
  const runwayMat = new THREE.MeshStandardMaterial({ color: COLOR_RUNWAY });
  const runwayMesh = new THREE.Mesh(runwayGeo, runwayMat);
  runwayMesh.position.set(0, 0.51, 1200);
  runwayMesh.receiveShadow = true;
  runwayGroup.add(runwayMesh);

  const edgeGeo = new THREE.BoxGeometry(620, 1, 44);
  const edgeMat = new THREE.MeshStandardMaterial({ color: COLOR_RUNWAY_EDGE });
  const edgeMesh = new THREE.Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0.55, 1200);
  runwayGroup.add(edgeMesh);

  // Runway numbers/markings
  const markGeo = new THREE.BoxGeometry(20, 0.6, 8);
  const markMat = new THREE.MeshStandardMaterial({ color: COLOR_RUNWAY_EDGE });
  for (let i = 0; i < 6; i += 1) {
    const mark = new THREE.Mesh(markGeo, markMat);
    mark.position.set(-220 + i * 80, 0.54, 1200 - i * 40);
    runwayGroup.add(mark);
  }

  function updateRunway(runway) {
    runwayGroup.position.set(runway.x, 0, runway.z);
    runwayGroup.rotation.y = runway.heading;
  }

  // ---- Rings ----
  const ringGroup = new THREE.Group();
  scene.add(ringGroup);

  const ringGeo = new THREE.TorusGeometry(MISSION.ringRadius, 2, 8, 24);
  const ringMat = new THREE.MeshStandardMaterial({ color: COLOR_RING, emissive: 0x331100 });
  const ringMeshes = [];

  function createRingMesh(x, y, z) {
    const mesh = new THREE.Mesh(ringGeo, ringMat);
    mesh.position.set(x, y, z);
    ringGroup.add(mesh);
    ringMeshes.push(mesh);
    return mesh;
  }

  function updateRings(rings) {
    // Remove old
    while (ringMeshes.length > 0) {
      const m = ringMeshes.pop();
      ringGroup.remove(m);
    }
    for (const ring of rings) {
      createRingMesh(ring.x, ring.y, ring.z);
    }
  }

  // ---- Buildings ----
  const buildingGroup = new THREE.Group();
  scene.add(buildingGroup);
  const buildingGeo = new THREE.BoxGeometry(1, 1, 1);
  const buildingMats = [
    new THREE.MeshStandardMaterial({ color: 0x556644 }),
    new THREE.MeshStandardMaterial({ color: 0x445533 }),
    new THREE.MeshStandardMaterial({ color: 0x667755 }),
  ];
  const buildingMeshes = [];

  function createBuildingMesh(b) {
    const mesh = new THREE.Mesh(buildingGeo, buildingMats[Math.floor(Math.random() * buildingMats.length)]);
    mesh.scale.set(b.width, b.height, b.depth);
    mesh.position.set(b.x, b.height / 2, b.z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    buildingGroup.add(mesh);
    buildingMeshes.push(mesh);
  }

  function updateBuildings(buildings) {
    while (buildingMeshes.length > 0) {
      const m = buildingMeshes.pop();
      buildingGroup.remove(m);
    }
    for (const b of buildings) createBuildingMesh(b);
  }

  // ---- Trees ----
  const treeGroup = new THREE.Group();
  scene.add(treeGroup);
  const treeTrunkGeo = new THREE.CylinderGeometry(0.6, 0.9, 6, 8);
  const treeTrunkMat = new THREE.MeshStandardMaterial({ color: 0x3d2b1f });
  const treeTopGeo = new THREE.ConeGeometry(3, 8, 8);
  const treeTopMat = new THREE.MeshStandardMaterial({ color: 0x2d5a27 });
  const treeMeshes = [];

  function createTreeMesh(t) {
    const trunk = new THREE.Mesh(treeTrunkGeo, treeTrunkMat);
    trunk.position.set(t.x, 3, t.z);
    trunk.castShadow = true;
    trunk.receiveShadow = true;

    const top = new THREE.Mesh(treeTopGeo, treeTopMat);
    top.position.set(t.x, t.height - 2, t.z);
    top.castShadow = true;

    treeGroup.add(trunk);
    treeGroup.add(top);
    treeMeshes.push(trunk, top);
  }

  function updateTrees(trees) {
    while (treeMeshes.length > 0) {
      const m = treeMeshes.pop();
      treeGroup.remove(m);
    }
    for (const t of trees) createTreeMesh(t);
  }

  // ---- Plane model ----
  const planeGroup = new THREE.Group();
  scene.add(planeGroup);

  const fuselageGeo = new THREE.CylinderGeometry(1.4, 1.0, 16, 12);
  const fuselageMat = new THREE.MeshStandardMaterial({ color: COLOR_PLANE_BODY });
  const fuselage = new THREE.Mesh(fuselageGeo, fuselageMat);
  fuselage.rotation.z = Math.PI / 2;
  fuselage.castShadow = true;
  planeGroup.add(fuselage);

  const noseGeo = new THREE.ConeGeometry(1.0, 3, 12);
  const nose = new THREE.Mesh(noseGeo, fuselageMat);
  nose.position.set(9, 0, 0);
  nose.rotation.z = Math.PI / 2;
  nose.castShadow = true;
  planeGroup.add(nose);

  const wingGeo = new THREE.BoxGeometry(22, 0.5, 3);
  const wingMat = new THREE.MeshStandardMaterial({ color: COLOR_PLANE_WING });
  const wing = new THREE.Mesh(wingGeo, wingMat);
  wing.position.set(0, 0.2, 0);
  wing.castShadow = true;
  planeGroup.add(wing);

  const tailGeo = new THREE.BoxGeometry(6, 0.4, 5);
  const tailMat = new THREE.MeshStandardMaterial({ color: COLOR_PLANE_WING });
  const tail = new THREE.Mesh(tailGeo, tailMat);
  tail.position.set(-8, 1.6, 0);
  tail.castShadow = true;
  planeGroup.add(tail);

  const vtailGeo = new THREE.BoxGeometry(0.4, 5, 3);
  const vtail = new THREE.Mesh(vtailGeo, tailMat);
  vtail.position.set(-8, 4.2, 0);
  vtail.castShadow = true;
  planeGroup.add(vtail);

  const propGeo = new THREE.CylinderGeometry(0.15, 0.15, 1.2, 8);
  const propMat = new THREE.MeshStandardMaterial({ color: COLOR_PLANE_ACCENT });
  const propeller = new THREE.Mesh(propGeo, propMat);
  propeller.position.set(10.6, 0, 0);
  propeller.rotation.z = Math.PI / 2;
  planeGroup.add(propeller);

  const cockpitGeo = new THREE.SphereGeometry(0.9, 10, 10);
  const cockpitMat = new THREE.MeshStandardMaterial({ color: 0xbbddff, transparent: true, opacity: 0.6 });
  const cockpit = new THREE.Mesh(cockpitGeo, cockpitMat);
  cockpit.position.set(1, 0.4, 0);
  planeGroup.add(cockpit);

  // ---- Chase camera target ----
  let cameraTarget = { x: 0, y: 0, z: 0 };

  // ---- HUD overlay (HTML/CSS on top of canvas) ----
  const hud = document.createElement('div');
  hud.id = 'flight-hud';
  hud.style.position = 'absolute';
  hud.style.inset = '0';
  hud.style.pointerEvents = 'none';
  hud.style.fontFamily = "'Courier New', Courier, monospace";
  hud.style.color = '#e8f4ff';
  hud.style.zIndex = '10';

  const altEl = document.createElement('div');
  altEl.style.position = 'absolute';
  altEl.style.left = HUD.margin + 'px';
  altEl.style.top = HUD.margin + 'px';
  altEl.style.fontSize = HUD.fontSizeLarge + 'px';
  altEl.style.fontWeight = 'bold';
  altEl.style.textShadow = '0 0 6px rgba(0,0,0,0.8)';
  hud.appendChild(altEl);

  const spdEl = document.createElement('div');
  spdEl.style.position = 'absolute';
  spdEl.style.left = HUD.margin + 'px';
  spdEl.style.top = (HUD.margin + 40) + 'px';
  spdEl.style.fontSize = HUD.fontSize + 'px';
  spdEl.style.textShadow = '0 0 6px rgba(0,0,0,0.8)';
  hud.appendChild(spdEl);

  const hdgEl = document.createElement('div');
  hdgEl.style.position = 'absolute';
  hdgEl.style.right = HUD.margin + 'px';
  hdgEl.style.top = HUD.margin + 'px';
  hdgEl.style.fontSize = HUD.fontSizeLarge + 'px';
  hdgEl.style.fontWeight = 'bold';
  hdgEl.style.textAlign = 'right';
  hdgEl.style.textShadow = '0 0 6px rgba(0,0,0,0.8)';
  hud.appendChild(hdgEl);

  const fuelEl = document.createElement('div');
  fuelEl.style.position = 'absolute';
  fuelEl.style.right = HUD.margin + 'px';
  fuelEl.style.top = (HUD.margin + 40) + 'px';
  fuelEl.style.fontSize = HUD.fontSize + 'px';
  fuelEl.style.textAlign = 'right';
  fuelEl.style.textShadow = '0 0 6px rgba(0,0,0,0.8)';
  hud.appendChild(fuelEl);

  const dmgEl = document.createElement('div');
  dmgEl.style.position = 'absolute';
  dmgEl.style.left = HUD.margin + 'px';
  dmgEl.style.bottom = HUD.margin + 'px';
  dmgEl.style.fontSize = HUD.fontSize + 'px';
  dmgEl.style.textShadow = '0 0 6px rgba(0,0,0,0.8)';
  hud.appendChild(dmgEl);

  const missionEl = document.createElement('div');
  missionEl.style.position = 'absolute';
  missionEl.style.left = '50%';
  missionEl.style.top = HUD.margin + 'px';
  missionEl.style.transform = 'translateX(-50%)';
  missionEl.style.fontSize = HUD.fontSizeLarge + 'px';
  missionEl.style.fontWeight = 'bold';
  missionEl.style.textAlign = 'center';
  missionEl.style.textShadow = '0 0 8px rgba(0,0,0,0.9)';
  hud.appendChild(missionEl);

  // Crosshair
  const crosshair = document.createElement('div');
  crosshair.style.position = 'absolute';
  crosshair.style.left = '50%';
  crosshair.style.top = '50%';
  crosshair.style.width = '16px';
  crosshair.style.height = '16px';
  crosshair.style.border = '2px solid rgba(255,255,255,0.4)';
  crosshair.style.borderRadius = '50%';
  crosshair.style.transform = 'translate(-50%, -50%)';
  crosshair.style.pointerEvents = 'none';
  hud.appendChild(crosshair);

  canvas.parentNode.appendChild(hud);

  // ---- Resize ----
  function resize() {
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);
  resize();

  // ---- Draw ----
  let lastRingUpdate = 0;

  return {
    draw(state, screen, input) {
      const p = state.plane;
      const t = state.time;

      // Update ground near plane
      updateGround(p.x, p.z, state.getGroundHeight, state.getTerrainColor);

      // Update rings when they change
      if (t - lastRingUpdate > 0.1) {
        updateRings(state.rings);
        updateBuildings(state.buildings);
        updateTrees(state.trees);
        lastRingUpdate = t;
      }

      updateRunway(state.runway);

      // Sun position follows camera-ish (fixed in world)
      sunMesh.position.set(p.x + 200, p.y + 300, p.z + 100);
      sun.position.copy(sunMesh.position);

      // Plane model transform
      planeGroup.position.set(p.x, p.y, p.z);
      planeGroup.rotation.set(p.pitch, p.yaw, p.roll);
      propeller.rotation.z = p.propellerAngle;
      propeller.rotation.x = Math.PI / 2;

      // Damage flicker
      if (p.damage > 50 && Math.floor(t * 10) % 2 === 0) {
        fuselage.material.emissive.setHex(0x440000);
      } else {
        fuselage.material.emissive.setHex(0x000000);
      }

      // Chase camera
      const idealX = p.x - Math.sin(p.yaw) * CAMERA.chaseDistance * Math.cos(p.pitch);
      const idealY = p.y + CAMERA.chaseHeight + Math.sin(p.pitch) * CAMERA.chaseDistance;
      const idealZ = p.z - Math.cos(p.yaw) * CAMERA.chaseDistance * Math.cos(p.pitch);

      cameraTarget.x += (idealX - cameraTarget.x) * CAMERA.chaseLag;
      cameraTarget.y += (idealY - cameraTarget.y) * CAMERA.chaseLag;
      cameraTarget.z += (idealZ - cameraTarget.z) * CAMERA.chaseLag;

      camera.position.set(cameraTarget.x, cameraTarget.y, cameraTarget.z);
      const lookX = p.x - Math.sin(p.yaw) * CAMERA.lookAhead * Math.cos(p.pitch);
      const lookY = p.y + Math.sin(p.pitch) * CAMERA.lookAhead;
      const lookZ = p.z - Math.cos(p.yaw) * CAMERA.lookAhead * Math.cos(p.pitch);
      camera.lookAt(lookX, lookY, lookZ);

      // HUD text
      const headingDeg = Math.round(((p.yaw * 180 / Math.PI) + 360) % 360);
      altEl.textContent = `ALT ${Math.floor(p.altitude)} ft`;
      spdEl.textContent = `SPD ${Math.floor(p.speed)} kt`;
      hdgEl.textContent = `HDG ${headingDeg}°`;
      fuelEl.textContent = `FUEL ${Math.floor((p.fuel / PLANE.fuelCapacity) * 100)}%`;
      dmgEl.textContent = `DMG ${Math.floor(p.damage)}%`;

      if (state.mission === 'rings') {
        missionEl.textContent = `RINGS: ${state.ringsPassed} / ${MISSION.ringsPerMission}`;
      } else if (state.mission === 'land') {
        missionEl.textContent = 'LAND ON RUNWAY AHEAD';
      } else if (state.missionComplete) {
        missionEl.textContent = 'MISSION COMPLETE';
      }

      renderer.render(scene, camera);
    },

    destroy() {
      window.removeEventListener('resize', resize);
      canvas.parentNode.removeChild(hud);
    },

    getCanvas() { return canvas; },
  };
}

